s = input().strip().upper()
hex_chars = set("0123456789ABCDEF")

def extract_hex(txt):
    if ":" in txt and "-" not in txt and "." not in txt:
        parts = txt.split(":")
        if len(parts) == 6 and all(len(p) == 2 and all(c in hex_chars for c in p) for p in parts):
            return "".join(parts)
    elif "-" in txt and ":" not in txt and "." not in txt:
        parts = txt.split("-")
        if len(parts) == 6 and all(len(p) == 2 and all(c in hex_chars for c in p) for p in parts):
            return "".join(parts)
    elif "." in txt and ":" not in txt and "-" not in txt:
        parts = txt.split(".")
        if len(parts) == 3 and all(len(p) == 4 and all(c in hex_chars for c in p) for p in parts):
            return "".join(parts)
    elif len(txt) == 12 and all(c in hex_chars for c in txt):
        return txt
    return None

clean = extract_hex(s)
