s = input().strip().lower()
hex_set = set("0123456789abcdef")

def expand_ipv6(addr):
    if not addr or addr.count("::") > 1 or ":::" in addr:
        return None
    if "::" in addr:
        left_s, right_s = addr.split("::")
        left = left_s.split(":") if left_s else []
        right = right_s.split(":") if right_s else []
        missing = 8 - (len(left) + len(right))
        if missing < 1:
            return None
        groups = left + ["0"] * missing + right
    else:
        groups = addr.split(":")
        if len(groups) != 8:
            return None
    out = []
    for g in groups:
        if not (1 <= len(g) <= 4) or not all(c in hex_set for c in g):
            return None
        out.append(g.zfill(4))
    return ":".join(out)

res = expand_ipv6(s)
print(res if res else "INVALID_IPV6")

parts = input().strip().split(".")
if len(parts) != 4 or any(not p.isdigit() or (len(p) > 1 and p[0] == "0") or not (0 <= int(p) <= 255) for p in parts):
    print("INVALID_MASK")
else:
    a, b, c, d = (int(p) for p in parts)
    mask32 = (a << 24) | (b << 16) | (c << 8) | d
    inv = (~mask32) & 0xFFFFFFFF
    if (inv & (inv + 1)) != 0:
        print("INVALID_MASK")
    else:
        prefix = bin(mask32).count("1")
        wild = f"{(inv >> 24) & 0xFF}.{(inv >> 16) & 0xFF}.{(inv >> 8) & 0xFF}.{inv & 0xFF}"
        print(f"VALID | /{prefix} | Wildcard: {wild}")

def parse_ip(s):
    parts = s.split(".")
    if len(parts) != 4 or any(not p.isdigit() or (len(p) > 1 and p[0] == "0") or not (0 <= int(p) <= 255) for p in parts):
        return None
    a, b, c, d = (int(p) for p in parts)
    return (a << 24) | (b << 16) | (c << 8) | d

def fmt_ip(n):
    return f"{(n >> 24) & 0xFF}.{(n >> 16) & 0xFF}.{(n >> 8) & 0xFF}.{n & 0xFF}"

raw = input().strip()
if "/" not in raw:
    print("INVALID_CIDR")
else:
    ip_s, pref_s = raw.split("/", 1)
    ip32 = parse_ip(ip_s)
    if ip32 is None or not pref_s.isdigit() or (len(pref_s) > 1 and pref_s[0] == "0") or not (0 <= int(pref_s) <= 32):
        print("INVALID_CIDR")
    else:
        pref = int(pref_s)
        mask = 0 if pref == 0 else ((0xFFFFFFFF << (32 - pref)) & 0xFFFFFFFF)
        net = ip32 & mask
        bcast = net | ((~mask) & 0xFFFFFFFF)
        print(f"Network: {fmt_ip(net)}")
        print(f"Broadcast: {fmt_ip(bcast)}")
        if pref == 32:
            print(f"Range: {fmt_ip(net)} (Single Host)")
            print("Usable Hosts: 1")
        elif pref == 31:
            print(f"Range: {fmt_ip(net)} - {fmt_ip(bcast)} (P2P)")
            print("Usable Hosts: 2")
        else:
            hosts = (1 << (32 - pref)) - 2
            print(f"Range: {fmt_ip(net + 1)} - {fmt_ip(bcast - 1)}")
            print(f"Usable Hosts: {hosts}")

def parse_ip(s):
    parts = s.split(".")
    if len(parts) != 4 or any(not p.isdigit() or (len(p) > 1 and p[0] == "0") or not (0 <= int(p) <= 255) for p in parts):
        return None
    a, b, c, d = (int(p) for p in parts)
    return (a << 24) | (b << 16) | (c << 8) | d

def parse_mask(m):
    if m.startswith("/"):
        p = m[1:]
        if not p.isdigit() or (len(p) > 1 and p[0] == "0") or not (0 <= int(p) <= 32):
            return None
        pref = int(p)
        return 0 if pref == 0 else ((0xFFFFFFFF << (32 - pref)) & 0xFFFFFFFF)
    val = parse_ip(m)
    if val is None:
        return None
    inv = (~val) & 0xFFFFFFFF
    return val if (inv & (inv + 1)) == 0 else None

def fmt_ip(n):
    return f"{(n >> 24) & 0xFF}.{(n >> 16) & 0xFF}.{(n >> 8) & 0xFF}.{n & 0xFF}"

