FLAGS = [(32, "URG"), (16, "ACK"), (8, "PSH"), (4, "RST"), (2, "SYN"), (1, "FIN")]
raw = input().strip()
try:
    val = int(raw)
except ValueError:
    val = -1

if not (0 <= val <= 63):
    print("INVALID_FLAGS")
else:
    active = [name for bit, name in FLAGS if val & bit]
    flag_str = ", ".join(active) if active else "NONE"
    if val == 0:
        phase = "ANOMALY_NULL"
    elif val & 4:
        phase = "CONNECTION_RESET"
    elif (val & 2) and (val & 16):
        phase = "HANDSHAKE_SYN_ACK"
    elif (val & 2) and not (val & 1):
        phase = "HANDSHAKE_SYN"
    elif (val & 1) and not (val & 2):
        phase = "TEARDOWN_FIN"
    elif val & 16:
        phase = "DATA_OR_ACK"
    else:
        phase = "OTHER"
