METHODS = {"GET", "POST", "PUT", "PATCH", "DELETE", "HEAD", "OPTIONS"}
n = int(input().strip())
lines = [input().rstrip("\n") for _ in range(n)]

if not lines:
    print("BAD_REQUEST")
else:
    req_parts = lines[0].split()
    ok = len(req_parts) == 3 and req_parts[0] in METHODS and req_parts[2] in ("HTTP/1.0", "HTTP/1.1") and req_parts[1].startswith("/")
    headers = {}
    if ok:
        for hline in lines[1:]:
            if ":" not in hline:
                ok = False
                break
            k, v = hline.split(":", 1)
            k = k.strip().lower()
            v = v.strip()
            if not k:
                ok = False
                break
            headers[k] = v
    if ok and req_parts[2] == "HTTP/1.1" and not headers.get("host"):
        ok = False
    if not ok:
        print("BAD_REQUEST")
    else:
        host = headers.get("host", "NONE")
        print(f"VALID | {req_parts[0]} {req_parts[1]} | Host: {host} | Headers: {len(lines) - 1}")

IDEMPOTENT = {"GET", "HEAD", "PUT", "DELETE", "OPTIONS"}
method, code_s = input().strip().split()
hdr = input().strip()

try:
    code = int(code_s)
except ValueError:
    code = -1

hkey, hval = "", ""
if "=" in hdr:
    hkey, hval = hdr.split("=", 1)
    hkey = hkey.strip().lower()
    hval = hval.strip()

if not (100 <= code <= 599):
    print("INVALID_STATUS")
else:
    tier = code // 100
    if tier == 1:
        cls, action = "INFO", "WAIT"
    elif tier == 2:
        cls, action = "SUCCESS", "DONE"
    elif tier == 3:
        cls = "REDIRECT"
        loc = hval if hkey == "location" and hval else "MISSING"
        action = f"FOLLOW:{loc}"
    elif tier == 4:
        cls = "CLIENT_ERROR"
        if code == 429:
            wait = hval if hkey == "retry-after" and hval else "DEFAULT"
            action = f"RETRY_AFTER:{wait}"
        else:
            action = "FAIL_FAST"
    else:
        cls = "SERVER_ERROR"
        if method.upper() in IDEMPOTENT or code in (502, 503, 504):
            action = "RETRY_BACKOFF"
        else:
            action = "FAIL_SAFE"
    print(f"Class: {cls} | Action: {action}")

q = int(input().strip())
cache = {}
hits = expired = miss = 0

for _ in range(q):
    parts = input().strip().split()
    cmd = parts[0]
    if cmd == "SET":
        now = int(parts[1])
        dom = parts[2].lower()
        ip = parts[3]
        ttl = int(parts[4])
        cache[dom] = (ip, now + ttl)
    elif cmd == "RESOLVE":
        now = int(parts[1])
        dom = parts[2].lower()
        if dom not in cache:
            miss += 1
            print("MISS")
        else:
            ip, exp = cache[dom]
            if now < exp:
                hits += 1
                print(f"HIT {ip}")
            else:
                expired += 1
                del cache[dom]
                print("EXPIRED")
    elif cmd == "STATS":
        print(f"Hits:{hits} Expired:{expired} Miss:{miss}")

import json

raw = input().strip()
try:
    obj = json.loads(raw)
except json.JSONDecodeError:
    obj = None

if not isinstance(obj, dict):
    print("PARSE_ERROR")
elif obj.get("status") == "error" or isinstance(obj.get("error"), dict):
    err = obj.get("error")
    if isinstance(err, dict):
        msg = err.get("message", "Unknown error")
    else:
        msg = obj.get("message", "Unknown error")
    print(f"API_ERROR: {msg}")
else:
    data = obj.get("data")
    items = data.get("items") if isinstance(data, dict) else None
    if not isinstance(items, list):
        print("PARSE_ERROR")
    else:
        healthy = 0
        latencies = []
        for item in items:
            if not isinstance(item, dict):
                continue
            if item.get("ok") is True:
                healthy += 1
            lat = item.get("latency_ms")
            if isinstance(lat, (int, float)) and not isinstance(lat, bool):
                latencies.append(float(lat))
        avg = sum(latencies) / len(latencies) if latencies else 0.0
        print(f"Total:{len(items)} Healthy:{healthy} AvgLatency:{avg:.1f}ms")
